-- A member has at most one pending renewal attestation per season.
--
-- Renew used to insert a new pending attestation on every call, so a repeated
-- click, or the member page Re-send (which called Renew), left the member with
-- two pending rows: listed twice on the admin Requests page and holding two
-- live links. Renew now re-issues the link on the existing row; this index is
-- the backstop.
--
-- Scoped confirmations (credential_ids set: an admin re-added a fob the
-- member holds) are a separate thread and are not covered. They are already
-- limited to one pending row per fob in the Add Credential route.

-- 1. Close existing duplicates, keeping the newest row of each group (the
--    link in the most recent email). Older rows become `expired`, the same
--    state the nightly job gives a lapsed attestation. Done per tenant with
--    the tenant context set, so it behaves the same whether or not the
--    migrating role is subject to row-level security.
DO $$
DECLARE
  t record;
BEGIN
  FOR t IN SELECT id FROM tenants LOOP
    PERFORM set_config('app.current_tenant_id', t.id::text, true);
    UPDATE attestation_requests a
       SET status = 'expired', updated_at = now()
     WHERE a.tenant_id = t.id
       AND a.status = 'pending'
       AND a.credential_ids IS NULL
       AND EXISTS (
         SELECT 1
           FROM attestation_requests b
          WHERE b.tenant_id = a.tenant_id
            AND b.user_id = a.user_id
            AND b.season = a.season
            AND b.status = 'pending'
            AND b.credential_ids IS NULL
            AND (b.created_at, b.id) > (a.created_at, a.id)
       );
  END LOOP;
  PERFORM set_config('app.current_tenant_id', '', true);
END $$;
